pool.shutdown();
if (!pool.awaitTermination(30, TimeUnit.SECONDS)) pool.shutdownNow();

var limit = new Semaphore(512);                 // admission control, not a pool
Thread.ofVirtual().name("performer-", 0).factory();
try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    for (Message msg : batch) {
        limit.acquire();
        executor.submit(() -> {
            try { handle(msg); } finally { limit.release(); }
        });
    }
}   // close() waits for the tasks, as with any ExecutorService
